--
-- Name: vw_subject_acl; Type: VIEW; Schema: public; Owner: uudex_user
--

CREATE VIEW public.vw_subject_acl AS
 SELECT subject_acl.subject_acl_id AS subject_acl_subject_acl_id,
    subject.subject_name,
    subject.subject_uuid,
    participanta.participant_short_name AS owner_short_name,
    privilege.privilege_name AS privilege_privilege_name,
    grant_scope.grant_scope_name AS grant_scope_grant_scope_name,
    participant.participant_uuid AS granted_participant_uuid,
    participant.participant_short_name AS granted_short_name
   FROM ((((((public.subject
     LEFT JOIN public.subject_acl ON ((subject.subject_id = subject_acl.subject_id)))
     LEFT JOIN public.privilege ON ((privilege.privilege_id = subject_acl.privilege_id)))
     LEFT JOIN public.grant_scope ON ((grant_scope.grant_scope_id = subject_acl.grant_scope_id)))
     LEFT JOIN public.subject_acl_grant ON ((subject_acl.subject_acl_id = subject_acl_grant.subject_acl_id)))
     LEFT JOIN public.participant ON ((participant.participant_id = subject_acl_grant.participant_id)))
     LEFT JOIN public.participant participanta ON ((participanta.participant_id = subject.owner_participant_id)))
  ORDER BY subject.subject_name;


ALTER TABLE public.vw_subject_acl OWNER TO uudex_user;

--
-- Name: vw_subject_policy; Type: VIEW; Schema: public; Owner: uudex_user
--

CREATE VIEW public.vw_subject_policy AS
 SELECT a.subject_policy_uuid,
    a.subject_policy_type,
    c.privilege_allowed_name,
    d.grant_scope_name,
    f.participant_uuid,
    f.participant_short_name
   FROM (((((public.subject_policy a
     JOIN public.subject_policy_acl_constraint b ON ((a.subject_policy_id = b.subject_policy_id)))
     JOIN public.privilege_allowed c ON ((b.privilege_allowed_id = c.privilege_allowed_id)))
     JOIN public.grant_scope d ON ((b.grant_scope_id = d.grant_scope_id)))
     LEFT JOIN public.subject_policy_grant_allowed e ON ((b.subject_policy_acl_constraint_id = e.subject_policy_acl_constraint_id)))
     LEFT JOIN public.participant f ON ((e.participant_id = f.participant_id)))
  ORDER BY a.subject_policy_uuid;


ALTER TABLE public.vw_subject_policy OWNER TO uudex_user;

--
-- Name: vw_subscription_subjects; Type: VIEW; Schema: public; Owner: uudex_user
--

CREATE VIEW public.vw_subscription_subjects AS
 SELECT c.subject_uuid,
    c.subject_name,
    a.subscription_id,
    a.subscription_uuid,
    a.subscription_name,
    a.subscription_state,
    b.preferred_fulfillment_type,
    c.backing_exchange_name,
    b.backing_queue_name,
    a.owner_endpoint_id,
    d.endpoint_user_name,
    a.create_datetime
   FROM (((public.subscription a
     LEFT JOIN public.subscription_subject b ON ((a.subscription_id = b.subscription_id)))
     LEFT JOIN public.subject c ON ((b.subject_id = c.subject_id)))
     LEFT JOIN public.endpoint d ON ((a.owner_endpoint_id = d.endpoint_id)))
  ORDER BY a.subscription_name, c.subject_name;


ALTER TABLE public.vw_subscription_subjects OWNER TO uudex_user;

